// MODELING OBJECT FILE RELOCATION ENTRY (Generic/ELF Style)
typedef unsigned long Addr;
typedef unsigned int  Info;

struct RelocationEntry {
    Addr r_offset; // Offset within target section to patch
    Info r_info;   // Contains Symbol Index and Relocation Type
};

// Linker uses these to decode r_info:
#define R_GET_SYM_INDEX(info) ((info) >> 8)
#define R_GET_TYPE(info)      ((unsigned char)(info))

// Example Relocation Type
const int R_TYPE_32 = 0x01; // Absolute 32-bit address patch
const int R_TYPE_PC32 = 0x02; // PC-Relative 32-bit address patch

// Linker formula: *r_offset = S + A - P (where S=Symbol, A=Addend, P=r_offset)
